args.ReplacementContent:
useEffect(() => {
  const loadStoreStatus = async () => {
    const { data } = await supabase.from('settings').select('key, value').in('key', ['manual_store_closed', 'store_status', 'paused_until', 'bot_active']);
    const getVal = (k: string) => data?.find(d => d.key === k)?.value;

    setManualClosed(getVal('manual_store_closed') === true);
    setStoreStatus(getVal('store_status') || 'open');
    setPausedUntil(getVal('paused_until') || null);
    if (getVal('bot_active') !== undefined) {
      setIsBotActive(Boolean(getVal('bot_active')));
    }
  };
  loadStoreStatus();

  const botSub = supabase
    .channel('admin_bot_settings_dashboard')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'settings', filter: 'key=eq.bot_active' }, (payload) => {
      if (payload.new && 'value' in payload.new) {
        setIsBotActive(Boolean(payload.new.value));
      }
    })
    .subscribe();

  return () => {
    supabase.removeChannel(botSub);
  };
}, []);

